//go:build linux

package main

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"runtime"
	"strconv"
	"strings"
	"time"

	"golang.org/x/sys/unix"
)

const liveSealBudget = 5 * time.Second

// liveSealBinding is generated by ROOT before ARM, not by a controller. The
// generation is independent of legacy journal version and changes on reuse.
type liveSealBinding struct {
	UID            uint32 `json:"uid"`
	Index          int    `json:"index"`
	Nonce          string `json:"nonce"`
	Generation     uint64 `json:"generation"`
	ParentPID      int    `json:"parent_pid"`
	ParentIdentity string `json:"parent_identity"`
	AnchorDev      uint64 `json:"anchor_dev"`
	AnchorIno      uint64 `json:"anchor_ino"`
	CgroupDev      uint64 `json:"cgroup_dev"`
	CgroupIno      uint64 `json:"cgroup_ino"`
}

type liveReservation struct {
	Version int             `json:"version"`
	Kind    string          `json:"kind"`
	Binding liveSealBinding `json:"binding"`
	Network *networkJournal `json:"network,omitempty"`
}

type liveSealPhase string

const (
	liveSealOpen     liveSealPhase = "open"
	liveSealSealing  liveSealPhase = "cgroup-sealing"
	liveSealRecorded liveSealPhase = "cgroup-sealed-recorded"
)

type liveSealRecord struct {
	Version int             `json:"version"`
	Kind    string          `json:"kind"`
	Binding liveSealBinding `json:"binding"`
	Phase   liveSealPhase   `json:"phase"`
}

// This authority proves only the durable cgroup barrier, not layout cleanup,
// policy outcome, process reaping, or permission to release the slot.
type verifiedLiveCgroupSeal struct{ binding liveSealBinding }

func validateLiveSealBinding(slot *launchSlot, b liveSealBinding) error {
	if slot == nil || b.UID == 0 || b.UID != slot.UID || b.Index != slot.Index || b.Index < 0 || b.Index >= launchSlotsPerUID || b.Generation == 0 || b.ParentPID <= 0 || b.ParentIdentity == "" || len(b.ParentIdentity) > 128 || b.AnchorIno == 0 || b.CgroupIno == 0 {
		return errors.New("invalid live seal binding")
	}
	n, err := hex.DecodeString(b.Nonce)
	if err != nil || len(n) != 32 || hex.EncodeToString(n) != b.Nonce {
		return errors.New("invalid live seal nonce")
	}
	return nil
}
func validateLiveReservation(slot *launchSlot, r liveReservation) error {
	if r.Version != 2 || r.Kind != "live-reservation" || r.Network != nil {
		return errors.New("invalid no-network live reservation")
	}
	return validateLiveSealBinding(slot, r.Binding)
}
func validateLiveSealRecord(slot *launchSlot, r liveSealRecord) error {
	if r.Version != 2 || r.Kind != "live-cgroup-seal" {
		return errors.New("invalid live seal record")
	}
	if err := validateLiveSealBinding(slot, r.Binding); err != nil {
		return err
	}
	switch r.Phase {
	case liveSealOpen, liveSealSealing, liveSealRecorded:
		return nil
	}
	return errors.New("unknown live seal phase")
}
func liveReservationName(slot *launchSlot) string {
	return slotName(slot.UID, slot.Index) + ".live-reservation"
}
func liveSealName(slot *launchSlot) string { return slotName(slot.UID, slot.Index) + ".live-seal" }

// writeLiveRecord uses distinct fixed names for reservation and watchdog seal.
// A partial temporary file is never overwritten, including after a crash.
func writeLiveRecord(baseFD int, name string, value any, create bool, owner uint32) error {
	data, err := json.Marshal(value)
	if err != nil || len(data) > 4096 {
		return errors.New("invalid live record")
	}
	fd, err := unix.Openat(baseFD, name+".pending", unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0o600)
	if err != nil {
		return err
	}
	f := os.NewFile(uintptr(fd), "live-record")
	var st unix.Stat_t
	if err = unix.Fchmod(fd, 0o600); err == nil {
		err = unix.Fstat(fd, &st)
	}
	if err == nil && (st.Uid != owner || st.Mode&unix.S_IFMT != unix.S_IFREG || st.Mode&0o7777 != 0o600 || st.Nlink != 1) {
		err = errors.New("unsafe new live record")
	}
	if err == nil {
		var n int
		n, err = f.Write(data)
		if err == nil && n != len(data) {
			err = io.ErrShortWrite
		}
	}
	if err == nil {
		err = f.Sync()
	}
	closeErr := f.Close()
	if err != nil {
		return err
	}
	if closeErr != nil {
		return closeErr
	}
	if create {
		err = unix.Renameat2(baseFD, name+".pending", baseFD, name, unix.RENAME_NOREPLACE)
	} else {
		err = unix.Renameat(baseFD, name+".pending", baseFD, name)
	}
	if err != nil {
		return err
	}
	return unix.Fsync(baseFD)
}
func readLiveRecord(baseFD int, name string, owner uint32, value any) (bool, error) {
	var st unix.Stat_t
	err := unix.Fstatat(baseFD, name+".pending", &st, unix.AT_SYMLINK_NOFOLLOW)
	if err == nil {
		return false, errors.New("partial live record quarantined")
	}
	if !errors.Is(err, unix.ENOENT) {
		return false, err
	}
	fd, err := unix.Openat(baseFD, name, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC|unix.O_NONBLOCK, 0)
	if errors.Is(err, unix.ENOENT) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	f := os.NewFile(uintptr(fd), "live-record")
	defer f.Close()
	if err := unix.Fstat(fd, &st); err != nil {
		return false, err
	}
	if st.Mode&unix.S_IFMT != unix.S_IFREG || st.Mode&0o7777 != 0o600 || st.Uid != owner || st.Nlink != 1 || st.Size <= 0 || st.Size > 4096 {
		return false, errors.New("unsafe live record")
	}
	data, err := io.ReadAll(io.LimitReader(f, 4097))
	if err != nil {
		return false, err
	}
	d := json.NewDecoder(bytes.NewReader(data))
	d.DisallowUnknownFields()
	if err := d.Decode(value); err != nil || d.Decode(new(any)) != io.EOF {
		return false, errors.New("invalid live record JSON")
	}
	canonical, err := json.Marshal(value)
	if err != nil || !bytes.Equal(data, canonical) {
		return false, errors.New("noncanonical live record")
	}
	return true, nil
}
func readLiveReservation(baseFD int, slot *launchSlot, owner uint32) (liveReservation, bool, error) {
	var r liveReservation
	if slot == nil {
		return r, false, errors.New("missing live slot")
	}
	ok, err := readLiveRecord(baseFD, liveReservationName(slot), owner, &r)
	if err == nil && ok {
		err = validateLiveReservation(slot, r)
	}
	return r, ok, err
}
func readLiveSeal(baseFD int, slot *launchSlot, owner uint32) (liveSealRecord, bool, error) {
	var r liveSealRecord
	if slot == nil {
		return r, false, errors.New("missing live slot")
	}
	ok, err := readLiveRecord(baseFD, liveSealName(slot), owner, &r)
	if err == nil && ok {
		err = validateLiveSealRecord(slot, r)
	}
	return r, ok, err
}

// reserveLiveCgroup is a pre-ARM operation under the retained slot lock after
// previous watchdogs have been reaped. It never upgrades a legacy record or
// overwrites an old reservation or any existing seal marker.
func reserveLiveCgroup(baseFD int, slot *launchSlot, r liveReservation) error {
	if os.Geteuid() != 0 {
		return errors.New("ROOT live reservation required")
	}
	if err := validateLiveReservation(slot, r); err != nil {
		return err
	}
	j, ok, err := readJournal(baseFD, slot, 0)
	if err != nil || !ok || !liveReservationMatchesLegacy(slot, r.Binding, j) {
		return errors.Join(errors.New("live reservation legacy binding or network mismatch"), err)
	}
	for _, name := range []string{liveSealName(slot), liveSealName(slot) + ".pending"} {
		exists, err := objectExists(baseFD, name)
		if err != nil {
			return err
		}
		if exists {
			return errors.New("existing live seal quarantined")
		}
	}
	return writeLiveRecord(baseFD, liveReservationName(slot), r, true, 0)
}

// initializeLiveSeal is called by the watchdog before ARM, never by the
// contained layout writer. All subsequent transitions are watchdog-only.
func initializeLiveSeal(baseFD int, slot *launchSlot, b liveSealBinding) error {
	if os.Geteuid() != 0 {
		return errors.New("ROOT live watchdog required")
	}
	r, ok, err := readLiveReservation(baseFD, slot, 0)
	if err != nil || !ok || r.Binding != b {
		return errors.Join(errors.New("live reservation mismatch"), err)
	}
	return writeLiveRecord(baseFD, liveSealName(slot), liveSealRecord{2, "live-cgroup-seal", b, liveSealOpen}, true, 0)
}

// liveSealOps is per-instance test injection; production is constructed only
// by newLiveSealBarrier and uses real cgroup and filesystem syscalls.
type liveSealOps struct {
	now             func() time.Time
	kill            func(int) error
	drain           func(int, time.Time) error
	readReservation func() (liveReservation, bool, error)
	readLegacy      func() (slotJournal, bool, error)
	readSeal        func() (liveSealRecord, bool, error)
	writeSeal       func(liveSealRecord) error
	checkCgroup     func() error
	removeCgroup    func() error
}
type liveSealBarrier struct {
	original *os.File
	fd       int
	slot     *launchSlot
	binding  liveSealBinding
	ops      liveSealOps
}

func newLiveSealBarrier(baseFD, parentFD int, original *os.File, slot *launchSlot, b liveSealBinding) (*liveSealBarrier, error) {
	if os.Geteuid() != 0 || original == nil || slot == nil {
		return nil, errors.New("missing ROOT live seal authority")
	}
	if err := validateLiveSealBinding(slot, b); err != nil {
		return nil, err
	}
	fd := int(original.Fd())
	j := slotJournal{CgroupDev: b.CgroupDev, CgroupIno: b.CgroupIno}
	ops := liveSealOps{
		now: time.Now, kill: liveCgroupKill, drain: liveCgroupDrain,
		readReservation: func() (liveReservation, bool, error) { return readLiveReservation(baseFD, slot, 0) },
		readLegacy:      func() (slotJournal, bool, error) { return readJournal(baseFD, slot, 0) },
		readSeal:        func() (liveSealRecord, bool, error) { return readLiveSeal(baseFD, slot, 0) },
		writeSeal: func(r liveSealRecord) error {
			if err := validateLiveSealRecord(slot, r); err != nil {
				return err
			}
			return writeLiveRecord(baseFD, liveSealName(slot), r, false, 0)
		},
		checkCgroup:  func() error { return checkLiveWatchCgroup(fd, parentFD, slot, j) },
		removeCgroup: func() error { return unix.Unlinkat(parentFD, slotName(slot.UID, slot.Index), unix.AT_REMOVEDIR) },
	}
	return &liveSealBarrier{original: original, fd: fd, slot: slot, binding: b, ops: ops}, nil
}
func (s *liveSealBarrier) seal() (*verifiedLiveCgroupSeal, error) {
	defer runtime.KeepAlive(s.original)
	// Kill must precede any record read, sync, validation or diagnostics.
	deadline := s.ops.now().Add(liveSealBudget)
	checkTime := func() error {
		if !s.ops.now().Before(deadline) {
			return errors.New("live seal budget exhausted")
		}
		return nil
	}
	if err := s.ops.kill(s.fd); err != nil {
		return nil, fmt.Errorf("live kill quarantined: %w", err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	if err := s.ops.drain(s.fd, deadline); err != nil {
		return nil, fmt.Errorf("live drain quarantined: %w", err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	r, ok, err := s.ops.readReservation()
	if err != nil || !ok || validateLiveReservation(s.slot, r) != nil || r.Binding != s.binding {
		return nil, errors.Join(errors.New("live reservation quarantined"), err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	legacy, ok, err := s.ops.readLegacy()
	if err != nil || !ok || !liveReservationMatchesLegacy(s.slot, s.binding, legacy) {
		return nil, errors.Join(errors.New("live legacy binding or network quarantined"), err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	record, ok, err := s.ops.readSeal()
	if err != nil || !ok || validateLiveSealRecord(s.slot, record) != nil || record.Binding != s.binding || record.Phase != liveSealOpen {
		return nil, errors.Join(errors.New("live seal state quarantined"), err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	record.Phase = liveSealSealing
	if err := s.ops.writeSeal(record); err != nil {
		return nil, fmt.Errorf("live sealing record uncertain: %w", err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	if err := s.ops.checkCgroup(); err != nil {
		return nil, fmt.Errorf("live cgroup identity quarantined: %w", err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	if err := s.ops.removeCgroup(); err != nil {
		if errors.Is(err, unix.EBUSY) && checkTime() == nil {
			err = errors.Join(err, s.ops.kill(s.fd))
		}
		return nil, fmt.Errorf("live cgroup removal quarantined: %w", err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	record.Phase = liveSealRecorded
	if err := s.ops.writeSeal(record); err != nil {
		return nil, fmt.Errorf("live sealed record uncertain: %w", err)
	}
	if err := checkTime(); err != nil {
		return nil, err
	}
	return &verifiedLiveCgroupSeal{binding: s.binding}, nil
}

func liveReservationMatchesLegacy(slot *launchSlot, b liveSealBinding, j slotJournal) bool {
	return validateJournal(slot, j) == nil && j.Phase == "ready" && j.Network == nil &&
		b.Nonce == j.Nonce && b.ParentPID == j.ParentPID && b.ParentIdentity == j.ParentIdentity &&
		b.AnchorDev == j.AnchorDev && b.AnchorIno == j.AnchorIno && b.CgroupDev == j.CgroupDev && b.CgroupIno == j.CgroupIno
}

// rejectLiveSlotMarkers prevents legacy cleanup from interpreting a reserved
// live slot as an ordinary v1 slot. Even a partial or corrupt marker blocks it.
func rejectLiveSlotMarkers(baseFD int, slot *launchSlot) error {
	if slot == nil {
		return errors.New("missing slot")
	}
	for _, name := range []string{liveReservationName(slot), liveReservationName(slot) + ".pending", liveSealName(slot), liveSealName(slot) + ".pending"} {
		exists, err := objectExists(baseFD, name)
		if err != nil {
			return err
		}
		if exists {
			return errors.New("live slot requires live recovery; quarantined")
		}
	}
	return nil
}

// Recovery requires the slot lock and prior watchdog reaping (or a newly
// acquired independent lock after watchdog death). It must not race the seal
// writer's rename/fsync. It never infers success from a missing cgroup or
// pending state and does not inspect or remove layout.
func recoverLiveCgroupSeal(baseFD int, slot *launchSlot, b liveSealBinding) (*verifiedLiveCgroupSeal, error) {
	if os.Geteuid() != 0 {
		return nil, errors.New("ROOT live recovery required")
	}
	return readRecordedLiveCgroupSeal(baseFD, slot, b, 0)
}
func readRecordedLiveCgroupSeal(baseFD int, slot *launchSlot, b liveSealBinding, owner uint32) (*verifiedLiveCgroupSeal, error) {
	r, ok, err := readLiveReservation(baseFD, slot, owner)
	if err != nil || !ok || r.Binding != b {
		return nil, errors.Join(errors.New("live reservation quarantined"), err)
	}
	j, ok, err := readJournal(baseFD, slot, owner)
	if err != nil || !ok || !liveReservationMatchesLegacy(slot, b, j) {
		return nil, errors.Join(errors.New("live legacy binding or network quarantined"), err)
	}
	s, ok, err := readLiveSeal(baseFD, slot, owner)
	if err != nil || !ok || s.Binding != b || s.Phase != liveSealRecorded {
		return nil, errors.Join(errors.New("live seal recovery quarantined"), err)
	}
	return &verifiedLiveCgroupSeal{binding: b}, nil
}
func liveCgroupKill(fd int) error {
	f, err := unix.Openat(fd, "cgroup.kill", unix.O_WRONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return err
	}
	n, err := unix.Write(f, []byte("1\n"))
	closeErr := unix.Close(f)
	if err == nil && n != 2 {
		err = io.ErrShortWrite
	}
	return errors.Join(err, closeErr)
}
func liveCgroupDrain(fd int, deadline time.Time) error {
	for time.Now().Before(deadline) {
		events, err := unix.Openat(fd, "cgroup.events", unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		if err != nil {
			return err
		}
		f := os.NewFile(uintptr(events), "cgroup-events")
		data, err := io.ReadAll(io.LimitReader(f, 4097))
		closeErr := f.Close()
		if err != nil || closeErr != nil {
			return errors.Join(err, closeErr)
		}
		if len(data) > 4096 {
			return errors.New("invalid cgroup events")
		}
		pop := -1
		for _, line := range strings.Split(string(data), "\n") {
			fields := strings.Fields(line)
			if len(fields) == 0 || fields[0] != "populated" {
				continue
			}
			if len(fields) != 2 || pop != -1 {
				return errors.New("invalid populated state")
			}
			pop, err = strconv.Atoi(fields[1])
			if err != nil || (pop != 0 && pop != 1) {
				return errors.New("invalid populated state")
			}
		}
		if pop == 0 {
			return nil
		}
		if pop != 1 {
			return errors.New("missing populated state")
		}
		left := time.Until(deadline)
		if left <= 0 {
			break
		}
		if left > 20*time.Millisecond {
			left = 20 * time.Millisecond
		}
		time.Sleep(left)
	}
	return errors.New("live cgroup drain timeout")
}
